import React, { useEffect, useState } from "react";
import { deleteGalleryImage, fetchGalleryImages } from "../services/galleryService";
import useAuth from "../hooks/useAuth";
import useToast from "../hooks/useToast";
import "./GalleryPage.css";

const getImageSource = (image) =>
  image?.secure_url ||
  image?.url ||
  image?.imageUrl ||
  image?.path ||
  image?.src ||
  image?.image?.secure_url ||
  image?.image?.url ||
  image?.file?.secure_url ||
  image?.file?.url ||
  image?.image_url ||
  image?.img_url ||
  image?.publicUrl ||
  "";

const getImageAlt = (image, index) =>
  image?.alt ||
  image?.caption ||
  image?.title ||
  image?.description ||
  image?.filename ||
  image?.name ||
  image?.original_filename ||
  image?.public_id ||
  `Gallery image ${index + 1}`;

const isCloudinaryUrl = (source) => {
  try {
    const hostname = new URL(source).hostname.toLowerCase();
    return hostname === "cloudinary.com" || hostname.endsWith(".cloudinary.com");
  } catch {
    return false;
  }
};

const normalizeGalleryImages = (payload) => {
  if (Array.isArray(payload)) {
    return payload.map((image, index) => ({
      ...image,
      src: getImageSource(image),
      alt: getImageAlt(image, index),
    }));
  }

  if (payload && typeof payload === "object") {
    if (Array.isArray(payload.images)) {
      return payload.images.map((image, index) => ({
        ...image,
        src: getImageSource(image),
        alt: getImageAlt(image, index),
      }));
    }

    if (Array.isArray(payload.data)) {
      return payload.data.map((image, index) => ({
        ...image,
        src: getImageSource(image),
        alt: getImageAlt(image, index),
      }));
    }

    if (Array.isArray(payload.gallery)) {
      return payload.gallery.map((image, index) => ({
        ...image,
        src: getImageSource(image),
        alt: getImageAlt(image, index),
      }));
    }

    if (
      payload.secure_url ||
      payload.url ||
      payload.imageUrl ||
      payload.path ||
      payload.src ||
      payload.image?.secure_url ||
      payload.image?.url ||
      payload.file?.secure_url ||
      payload.file?.url
    ) {
      return [
        {
          ...payload,
          src: getImageSource(payload),
          alt: getImageAlt(payload, 0),
        },
      ];
    }
  }

  return [];
};

const GalleryPage = () => {
  const { user } = useAuth();
  const toast = useToast();
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [lightboxIndex, setLightboxIndex] = useState(null);
  const [deletingImageIds, setDeletingImageIds] = useState(() => new Set());

  useEffect(() => {
    let isMounted = true;

    const loadImages = async () => {
      setLoading(true);
      setError("");

      try {
        const result = await fetchGalleryImages();
        if (!isMounted) return;

        const normalizedImages = normalizeGalleryImages(result).filter((image) =>
          isCloudinaryUrl(image.src)
        );
        setImages(normalizedImages);
      } catch (fetchError) {
        if (!isMounted) return;
        setError(fetchError.message || "Unable to load gallery images.");
        setImages([]);
      } finally {
        if (isMounted) setLoading(false);
      }
    };

    loadImages();

    return () => {
      isMounted = false;
    };
  }, []);

  const openLightbox = (index) => setLightboxIndex(index);
  const closeLightbox = () => setLightboxIndex(null);

  const goNext = (e) => {
    e.stopPropagation();
    setLightboxIndex((prev) => (prev + 1) % images.length);
  };

  const goPrev = (e) => {
    e.stopPropagation();
    setLightboxIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const handleKeyDown = (e) => {
    if (lightboxIndex === null) return;
    if (e.key === "ArrowRight") goNext(e);
    if (e.key === "ArrowLeft") goPrev(e);
    if (e.key === "Escape") closeLightbox();
  };

  const handleDeleteImage = async (image, index) => {
    const imageId = image._id;
    if (!imageId || deletingImageIds.has(imageId)) return;

    const imageName = getImageAlt(image, index);
    if (
      !window.confirm(
        `Delete "${imageName}" from the gallery? This action cannot be undone.`
      )
    ) {
      return;
    }

    setDeletingImageIds((currentIds) => new Set(currentIds).add(imageId));

    try {
      const result = await deleteGalleryImage(imageId);
      const deletedId = result?.imageId || imageId;
      setImages((currentImages) =>
        currentImages.filter((currentImage) => currentImage._id !== deletedId)
      );
      toast.success(`"${imageName}" was deleted from the gallery.`);
    } catch (deleteError) {
      if (deleteError.status === 404) {
        setImages((currentImages) =>
          currentImages.filter((currentImage) => currentImage._id !== imageId)
        );
        toast.info(`"${imageName}" was already missing and has been removed from the gallery.`);
      } else {
        toast.error(
          deleteError.message || `Could not delete "${imageName}". Please try again.`
        );
      }
    } finally {
      setDeletingImageIds((currentIds) => {
        const nextIds = new Set(currentIds);
        nextIds.delete(imageId);
        return nextIds;
      });
    }
  };

  const visibleImages = images;
  const activeImage = visibleImages[lightboxIndex] || null;
  const isAdmin = user?.role === "admin";

  return (
    <div className="gallery-page" onKeyDown={handleKeyDown} tabIndex={-1}>
      <header className="gallery-header">
        <div className="gallery-header-inner">
          <h1>Our Gallery</h1>
          <p>
            Browse our coffee spaces and featured setups. Click any image to enlarge it.
          </p>
        </div>
      </header>

      <div className="gallery-content">
        {loading && (
          <div className="gallery-message gallery-loading">Loading gallery images…</div>
        )}

        {error && <div className="gallery-message gallery-error">{error}</div>}

        {!loading && visibleImages.length === 0 && (
          <div className="gallery-message gallery-empty">No images available yet.</div>
        )}

        {!loading && visibleImages.length > 0 && (
          <div className="gallery-grid">
            {visibleImages.map((image, index) => (
              <div
                key={`${image.src || image.url || image.path || index}`}
                className="gallery-card"
              >
                <div
                  className="gallery-item"
                  onClick={() => openLightbox(index)}
                  role="button"
                  tabIndex={0}
                  aria-label={`View full size: ${getImageAlt(image, index)}`}
                  onKeyDown={(e) => e.key === "Enter" && openLightbox(index)}
                >
                  <img src={getImageSource(image)} alt={getImageAlt(image, index)} />
                  <div className="gallery-item-overlay">
                    <svg
                      width="32"
                      height="32"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="white"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <circle cx="11" cy="11" r="8" />
                      <line x1="21" y1="21" x2="16.65" y2="16.65" />
                      <line x1="11" y1="8" x2="11" y2="14" />
                      <line x1="8" y1="11" x2="14" y2="11" />
                    </svg>
                  </div>
                </div>
                {isAdmin && (
                  <button
                    type="button"
                    className="gallery-delete-button"
                    aria-label={`Delete ${getImageAlt(image, index)}`}
                    title={
                      image._id
                        ? `Delete ${getImageAlt(image, index)}`
                        : "This image cannot be deleted because its ID is unavailable"
                    }
                    disabled={!image._id || deletingImageIds.has(image._id)}
                    onClick={() => handleDeleteImage(image, index)}
                  >
                    {deletingImageIds.has(image._id) ? "Deleting..." : "Delete"}
                  </button>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {lightboxIndex !== null && activeImage && (
        <div
          className="lightbox-overlay"
          onClick={closeLightbox}
          role="dialog"
          aria-modal="true"
          aria-label="Image lightbox"
        >
          <button
            className="lightbox-close"
            onClick={closeLightbox}
            aria-label="Close"
          >
            &times;
          </button>

          <button
            className="lightbox-nav lightbox-prev"
            onClick={goPrev}
            aria-label="Previous image"
          >
            &#8249;
          </button>

          <div className="lightbox-content" onClick={(e) => e.stopPropagation()}>
            <img src={getImageSource(activeImage)} alt={getImageAlt(activeImage, lightboxIndex)} />
            <p className="lightbox-caption">{getImageAlt(activeImage, lightboxIndex)}</p>
            <p className="lightbox-counter">
              {lightboxIndex + 1} / {visibleImages.length}
            </p>
          </div>

          <button
            className="lightbox-nav lightbox-next"
            onClick={goNext}
            aria-label="Next image"
          >
            &#8250;
          </button>
        </div>
      )}
    </div>
  );
};

export default GalleryPage;
